class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        # brute-force
        # sort the array first
        # iterate through the array
        # check if nums[i] == nums[i + 1] --> return true
        # return false
        # O(nlogn) O(1)
        # Optimised to O(n)
        counter = {}
        for num in nums:
            if num not in counter:
                counter[num] = 1
            else:
                return True

        return False
